(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[446]={"source_order":446,"notes":["The superscript after '223' is read as 'b', matching the folio label. In isolation it resembles '6'.","The faint ghost text was judged to be show-through, not faint pencil writing on this page. No legible words were identified.","The left edge shows the stacked edges of gutter leaves with ruling ticks. No target-page text is in the gutter.","The adjacent fol. 223 and fol. 224 contain catalogue entries (Rāmāyaṇa etc.). They are context only and none of their text is visible as fragments on this page.","I reviewed the overview and all six native tiles. The ruled page carries no catalogue entries, headings, cross-references or marginal or interlinear notes. The only exception is the folio number in the top left corner.","There are two short diagonal pencil strokes in the upper text area, at about [1130,725,245,195]. No letters can be made out, so they are not transcribed.","There is a faint short stroke with a small triangular tip in the middle-left area, at about [900,2225,45,90]. It is probably accidental and is not text.","Scattered dark specks in the lower middle area, at about [1180,3990,280,90], look like dirt or foxing rather than writing.","Very faint show-through or offset of handwriting from the other side of the leaf is visible across the ruled area. It is illegible and does not belong to this page, so it is not transcribed.","The left edge shows stacked gutter leaves with ruling ticks. There is no target-page text in the gutter, the outer margin or the bottom margin.","The adjacent pages fol. 223 and fol. 224 contain catalogue entries (Rāmāyaṇa etc.). They are context only, and no fragments of their text appear on this page.","The superscript after '223' is ambiguous between 'b' and '6'. The baseline dot may be a full stop or a stray mark."],"records":[{"id":"css-prod-0446-r001","local_id":"r001","source_order":446,"folio":"223b","folio_label":"fol. 223b","sequence":1,"page_id":"6dd77430-fd97-4823-8c9a-ffc921a7deb6","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"223ᵇ.","annotations":["Written in the top left corner of the leaf at about [390,280,140,135]. The numeral '223' sits on a slanting baseline.","A raised letter-like mark follows above and to the right of the final '3'. It is read as 'b', matching the supplied folio label 'fol. 223b'.","A dot follows the '3' at baseline level. It may be a full stop or a stray mark."],"uncertainties":["The raised mark after '223' could also be read as '6'. The reading 'b' is preferred because it matches the folio label.","The dot after '223' may be punctuation or an accidental mark.","The superscript after '223' is ambiguous between 'b' and '6'. The baseline dot may be a full stop or a stray mark.","Proposed literal_text (probable): 223[ᵇ?].. The raised character could equally be read as 'b' or '6'. Preferring 'b' because it matches the metadata label is an inference, so the literal transcription should mark the reading as uncertain."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[390,280,140,135]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[{"record_id":"r001","field_path":"literal_text","before":"223ᵇ.","after":"223[ᵇ?].","reason":"The raised character could equally be read as 'b' or '6'. Preferring 'b' because it matches the metadata label is an inference, so the literal transcription should mark the reading as uncertain.","source_block_ids":["b001"],"certainty":"probable","applied":false,"application_reason":"Retained as a proposal; source certainty is not secure"}],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/6dd77430-fd97-4823-8c9a-ffc921a7deb6.json","auditPath":"audit/pages/0446.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
